 function render(){rows.replaceChildren();const list=catalog?.rows||[],departments={cafe:'Кафе',rental:'Прокат',shared:'Общее'};if(!list.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=6;td.textContent='Записей за период нет.';tr.append(td);rows.append(tr);}for(const item of list){const tr=document.createElement('tr'),expense=document.createElement('td'),label=document.createElement('strong'),amount=document.createElement('small'),category=document.createElement('td'),span=document.createElement('span'),periodCell=document.createElement('td'),included=document.createElement('td'),payment=document.createElement('td'),actions=document.createElement('td'),actionGroup=document.createElement('div');label.textContent=item.name;amount.textContent=` · ${money(item.amountCents)}${item.active===false?' · отменён':''}`;expense.append(label,amount);span.textContent=`${categories[item.category]||'Другое'} · ${departments[item.department]||'Общее'}`;category.append(span);periodCell.textContent=`${item.from||'—'} – ${item.to||'—'}`;included.textContent=money(item.allocatedCents);payment.textContent=`${methods[item.method]||'Не оплачен'} · ${item.paidOn||'не оплачено'} · ${item.paidInPeriod?'оплачено за период':'не оплачено за период'}`;actionGroup.className='fe-row-actions';if(canEdit&&!pending&&item.active!==false){actionGroup.append(button('✎','Изменить расход',()=>setForm(item)),button('＋','Копировать в следующий месяц как черновик',()=>copyNextMonth(item)),button('×','Отменить запись без удаления истории',()=>cancelRecord(item)));}actions.append(actionGroup);tr.append(expense,category,periodCell,included,payment,actions);rows.append(tr);}const confirmed=catalog?.confirmed===true;document.getElementById('fe-confirm-state').textContent=confirmed?'Полнота расходов подтверждена для выбранного периода.':'Период не подтверждён; итоговая прибыль остаётся предварительной.';confirmButton.hidden=!canEdit||confirmed;confirmButton.disabled=!!pending;const newButton=document.getElementById('fe-new');newButton.hidden=!canEdit;newButton.disabled=!!pending;submit.disabled=!canEdit||!!pending;form.querySelectorAll('input,select').forEach(el=>{if(el.name!=='id')el.disabled=!canEdit||!!pending;});retry.hidden=!pending;cancelEdit.disabled=!!pending;syncCategory();}
 function nextMonth(day,delta=1){const source=new Date(`${day}T12:00:00Z`),target=new Date(Date.UTC(source.getUTCFullYear(),source.getUTCMonth()+delta,1)),last=new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth()+1,0)).getUTCDate();target.setUTCDate(Math.min(source.getUTCDate(),last));return target.toISOString().slice(0,10);}
