 function formDraft(){return {id:form.elements.id.value||null,name:form.elements.name.value,category:form.elements.category.value,department:form.elements.department.value,amount:form.elements.amount.value,included:form.elements.included.value,from:form.elements.from.value,to:form.elements.to.value,paidOn:form.elements.paidOn.value,method:form.elements.method.value,withdrawalId:form.elements.withdrawalId.value};}
 function applyDraft(draft){normalizedIncluded=false;formDirty=true;form.elements.id.value=draft.id||'';form.elements.name.value=draft.name||'';form.elements.category.value=draft.category||'other';form.elements.department.value=draft.department||'shared';form.elements.amount.value=draft.amount||'';form.elements.included.value=draft.included||'';form.elements.from.value=draft.from||period.from;form.elements.to.value=draft.to||period.to;form.elements.paidOn.value=draft.paidOn||'';form.elements.method.value=draft.method||'unpaid';fillWithdrawals();form.elements.withdrawalId.value=draft.withdrawalId||'';syncCategory();}
 function entryFromForm(active=true){syncCategory();const amountCents=rubToCents(form.elements.amount.value),includedCents=rubToCents(form.elements.included.value),category=form.elements.category.value,method=category==='depreciation'?'unpaid':form.elements.method.value,selected=form.elements.withdrawalId.selectedOptions[0];if(!form.reportValidity())return null;if(amountCents!==null&&(!Number.isSafeInteger(amountCents)||amountCents<0)){say('Проверьте сумму в рублях.',true);return null;}if(includedCents!==null&&(!Number.isSafeInteger(includedCents)||includedCents<0)){say('Проверьте сумму уже в себестоимости.',true);return null;}if(amountCents!==null&&includedCents!==null&&includedCents>amountCents){say('Уже включённая сумма не может быть больше суммы расхода.',true);return null;}if(form.elements.from.value>form.elements.to.value){say('Дата начала должна быть не позже даты окончания.',true);return null;}if(method==='withdrawal'&&(amountCents===null||!selected?.value||selected.dataset.day!==form.elements.paidOn.value||Number(selected.dataset.amount)!==amountCents)){say('Выберите изъятие с совпадающими датой оплаты и суммой.',true);return null;}return {id:form.elements.id.value||null,name:form.elements.name.value.trim(),category,department:form.elements.department.value,amountCents,includedCents,from:form.elements.from.value,to:form.elements.to.value,paidOn:method==='unpaid'?null:form.elements.paidOn.value||null,method,withdrawalId:method==='withdrawal'?Number(form.elements.withdrawalId.value):null,active};}
 async function load({preserve=false,notice='',forPeriod=null}={}){if(pending)return;period=forPeriod||range();if(!period.from||!period.to){say('Выберите даты отчёта.',true);return;}const generation=++catalogGeneration,draft=formDirty||preserve?formDraft():null;say('Загрузка расходов…');try{const result=await request({query:{...period}});if(generation!==catalogGeneration||pending)return;const currentDraft=formDirty?formDraft():draft;catalog=result;canEdit=catalog.canEdit===true;if(currentDraft)applyDraft(currentDraft);else setForm();render();say(notice||(canEdit?'Расходы загружены.':'Нет доступа к редактированию расходов.'));}catch(error){if(generation===catalogGeneration)say(error.message,true);}}
